    'profile_security_badge' => 'Profile & security',
    'profile_security_o1' => 'Your profile shows the same details used on invoices and ID cards.',
    'profile_security_o2' => 'Unknown logins are signed out, and you change your password if you think someone knows it.',
    'profile_security_o3' => 'Two-step login (2FA) is turned on when company rules require it.',
    'profile_security_purpose' => 'Your profile details are used on invoices, ID cards, payment accounts, and sales area. Security settings stop others from reaching your wallet.',
    'profile_security_s1' => 'Open Profile and check your full name, shop name, phone, email, and address as registered with the company.',
    'profile_security_s10' => 'Log out on shared computers when you finish.',
    'profile_security_s2' => 'Check your place code and sales area when shown. They affect area dealer rules and area reports.',
    'profile_security_s3' => 'Download your Partner ID Card PDF and Join Poster from Profile, when available, to bring in new members.',
    'profile_security_s4' => 'Open Security to change your password. Use a new password that you do not use anywhere else.',
    'profile_security_s5' => 'Check your logged-in devices and sign out any you do not know right away.',
    'profile_security_s6' => 'If two-step login (2FA) is on for staff, set it up and keep the recovery codes safe offline.',
